/* Compact Care home panels and once-completed learning. All records come from the shared model. */
(function(){
  'use strict';
  const M=window.MewLinkCare,D=window.MewLinkData,R=()=>window.MewLinkRefine;
  const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const stamp=t=>t&&Number.isFinite(Date.parse(t))?D.stamp(t):'Time not recorded';
  const sourceHTML=rows=>(rows||[]).map(s=>typeof s==='string'?'<p>'+esc(s)+'</p>':'<p>'+(s.url?'<a href="'+esc(s.url)+'" '+(/^https?:/i.test(s.url)?'target="_blank" rel="noopener noreferrer"':'')+'>'+esc(s.title||'Source record')+'</a>':esc(s.title||s.id||'Care record'))+(s.text?'<br>'+esc(s.text):'')+(s.when?'<br><small>'+esc(s.when)+'</small>':'')+'</p>').join('');
  const css=`:host{display:block;font-family:'Atkinson Hyperlegible',system-ui,sans-serif;color:#33261D;min-width:0}*{box-sizing:border-box}h2,h3,p{margin:0}h2{font:500 24px/1.2 Newsreader,serif}h3{font-size:15px;line-height:1.4}p{line-height:1.5}a{color:#7A4E33}button,input{font:inherit}button{cursor:pointer}button:focus-visible,a:focus-visible,input:focus-visible,summary:focus-visible{outline:3px solid #B8862A;outline-offset:3px}details{border-radius:16px;background:#F3ECE0}summary{cursor:pointer;min-height:48px;list-style:none;padding:12px 14px;display:flex;align-items:center;justify-content:space-between;gap:12px;font-size:14px;line-height:1.4}summary::-webkit-details-marker{display:none}.chevron{color:#7A4E33;flex:none}details[open]>summary .chevron{transform:rotate(180deg)}.body{padding:0 14px 14px}.note{font-size:12px;color:#776455;line-height:1.45}.entry{padding:12px 0;border-top:1px solid #E4D9C8;display:flex;flex-direction:column;gap:5px}.entry p{font-size:14px}.entry a{font-weight:700}.demo{font-size:11px;color:#776455}.sources{margin-top:3px;background:#FFFBF3}.sources summary{font-size:12px;min-height:34px;padding:6px 10px}.sources .body{font-size:12px;padding:0 10px 10px;overflow-wrap:anywhere}.sources p+p{margin-top:8px}.stack{display:flex;flex-direction:column;gap:12px}.alert{border-radius:16px;background:#F8E9DF;padding:14px;display:flex;flex-direction:column;gap:6px}.alert p{font-size:14px}.heading{font-size:17px;font-weight:700}.empty{font-size:14px;color:#776455;padding:10px 0}.case{padding:12px 0;border-top:1px solid #E4D9C8}.case h3{margin-bottom:6px}.case p{font-size:14px}.case a{display:inline-block;margin-top:7px;font-size:12px}.learn{height:100%;display:flex;flex-direction:column;background:#FAF6EF}.learn header{padding:14px 22px 12px;display:flex;flex-direction:column;gap:9px}.back{display:inline-flex;align-self:flex-start;min-height:44px;align-items:center;font-weight:700;text-decoration:none}.progress{display:flex;gap:6px}.progress span{height:5px;flex:1;border-radius:3px;background:#E8DFD1}.progress .read{background:#E3AE45}.learn main{flex:1;min-height:0;overflow:auto;padding:8px 22px 22px;display:flex;flex-direction:column;gap:18px}.learn-card{border-radius:24px;background:#FBF1D9;padding:22px;display:flex;flex-direction:column;gap:14px}.learn-card h3{font:500 27px/1.15 Newsreader,serif}.learn-card p{font-size:17px}.learn-card a{font-size:13px}.check{display:flex;gap:12px;align-items:flex-start;border:1px solid #E0D5C3;border-radius:16px;background:#FFFBF3;padding:16px;font-size:15px;line-height:1.5;cursor:pointer}.check input{margin-top:3px;accent-color:#33261D;width:20px;height:20px;flex:none}.learn footer{flex:none;border-top:1px solid #E8DFD1;padding:12px 22px calc(16px + env(safe-area-inset-bottom,0px));display:flex;gap:10px;background:#FAF6EF}.primary{border:0;background:#33261D;color:#FFFBF3;min-height:52px;border-radius:26px;padding:12px 18px;font-weight:700;flex:1}.primary:disabled{background:#E8DFD1;color:#8A7968;cursor:default}.secondary{border:1px solid #DCCDB8;background:transparent;color:#5C4636;min-height:52px;border-radius:26px;padding:12px 18px}.error{color:#9A4A26;font-size:14px}`;
  class SharedPanel extends HTMLElement{
    constructor(){super();this.attachShadow({mode:'open'});this.refresh=()=>this.render();}
    connectedCallback(){this.render();for(const ev of ['mewlink-data-changed','mewlink-care-changed','storage','focus'])window.addEventListener(ev,this.refresh);this.timer=setInterval(this.refresh,60000);}
    disconnectedCallback(){for(const ev of ['mewlink-data-changed','mewlink-care-changed','storage','focus'])window.removeEventListener(ev,this.refresh);clearInterval(this.timer);}
  }
  class Notifications extends SharedPanel{
    render(){const open=this.shadowRoot.querySelector('details')?.open,rows=(R()?.notifications()||[]).slice().sort((a,b)=>Date.parse(b.occurredAt)-Date.parse(a.occurredAt));
      this.shadowRoot.innerHTML='<style>'+css+'.notification-summary{gap:8px;min-height:32px;padding:6px 12px}.notification-title{font-size:14px;flex:none}.notification-preview{margin-left:auto;text-align:right;font-size:12px;min-width:0;overflow:hidden;white-space:nowrap;text-overflow:ellipsis}.notification-summary .chevron{font-size:12px}</style><details '+(open?'open':'')+'><summary class="notification-summary"><strong class="notification-title">Notification</strong><span class="note notification-preview">'+esc(rows[0]?.title||'All caught up')+(rows.length>1?' · +'+(rows.length-1):'')+'</span><span class="chevron" aria-hidden="true">⌄</span></summary><div class="body">'+(rows.length?rows.map(n=>'<article class="entry"><h3>'+esc(n.title)+'</h3><p class="note">'+esc(stamp(n.occurredAt))+(n.author?' · '+esc(n.author):'')+'</p><p>'+esc(n.detail||'')+'</p><details class="sources"><summary>View source</summary><div class="body">'+(sourceHTML(n.sources)||'<p>Related care record; details are shown above.</p>')+'</div></details></article>').join(''):'<p class="empty">New recorded care events will appear here.</p>')+'</div></details>';}
  }
  class Alerts extends SharedPanel{
    render(){const rows=R()?.alerts()||[];this.shadowRoot.innerHTML='<style>'+css+'.alert-top{display:flex;align-items:center;gap:8px}.alert-top strong{font-size:14px}.alert-time{font-size:11px;color:#776455}.alert-tag{margin-left:auto;border-radius:99px;padding:3px 7px;font-size:11px;white-space:nowrap;background:#FCE0CB;color:#9A3F22}.alert h3{font-size:16px}.alert>.note{font-size:12px}</style><section class="stack" aria-label="Alerts"><h2>Alerts</h2>'+(rows.length?rows.map(n=>'<article class="alert"><header class="alert-top"><strong>'+esc(n.catName)+'</strong><time class="alert-time" title="'+esc(stamp(n.occurredAt))+'">'+esc(M.relativeTime(n.occurredAt))+'</time><span class="alert-tag">'+esc(n.tag)+'</span></header><h3>'+esc(n.title)+'</h3><p>'+esc(n.detail)+'</p><details class="sources"><summary>Source note</summary><div class="body">'+sourceHTML(n.sources)+'</div></details></article>').join(''):'<p class="empty">No recent care concern recorded.</p>')+'</section>';}
  }
  class Basics extends SharedPanel{
    render(){const open=this.shadowRoot.querySelector('details')?.open;this.shadowRoot.innerHTML='<style>'+css+'</style><details '+(open?'open':'')+'><summary><span class="heading">Care Basics</span><span class="chevron" aria-hidden="true">⌄</span></summary><div class="body"><p class="note">Quick examples for community-cat care. Open these whenever you need a reminder.</p>'+(R()?.basics()||[]).map(x=>'<article class="case"><h3>'+esc(x.title)+'</h3><p>'+esc(x.text)+'</p><a href="'+esc(x.sourceUrl)+'" target="_blank" rel="noopener noreferrer">'+esc(x.sourceTitle||'Care guidance')+' ↗</a></article>').join('')+'</div></details>';}
  }
  class LearnBasics extends HTMLElement{
    constructor(){super();this.attachShadow({mode:'open'});this.index=0;this.confirmed=new Set();this.error='';}
    connectedCallback(){if(!R()?.requiresLearning()){try{localStorage.removeItem('mewlink-learning-required');}catch(_){}location.hash='done';return;}this.render();}
    render(){const rows=R()?.basics()||[],x=rows[this.index];if(!x){this.shadowRoot.innerHTML='<style>'+css+'</style><p class="empty">Care guidance could not be loaded. Please reopen this step.</p>';return;}
      this.shadowRoot.innerHTML='<style>'+css+':host{height:100%;display:block}</style><section class="learn" aria-label="Care Basics onboarding"><header><a class="back" href="#join">‹ Back to your answers</a><p class="note">Before your first community-cat visit</p><h2>Care Basics</h2><p class="note">'+(this.index+1)+' of '+rows.length+' · Read and confirm each card once.</p><div class="progress" aria-hidden="true">'+rows.map((_,i)=>'<span class="'+(this.confirmed.has(i)||i===this.index?'read':'')+'"></span>').join('')+'</div></header><main><article class="learn-card"><h3>'+esc(x.title)+'</h3><p>'+esc(x.text)+'</p><a href="'+esc(x.sourceUrl)+'" target="_blank" rel="noopener noreferrer">'+esc(x.sourceTitle||'Trusted care guidance')+' ↗</a></article><label class="check"><input type="checkbox" '+(this.confirmed.has(this.index)?'checked':'')+'><span>I have read this card and understand the guidance.</span></label><p class="note">These basics stay available at the bottom of Care. Completion is remembered on this browser.</p>'+(this.error?'<p class="error" role="alert">'+esc(this.error)+'</p>':'')+'</main><footer>'+(this.index?'<button class="secondary" data-back>Previous</button>':'')+'<button class="primary" data-next '+(!this.confirmed.has(this.index)?'disabled':'')+'>'+(this.index===rows.length-1?'Finish basics':'Continue')+'</button></footer></section>';
      this.shadowRoot.querySelector('input').addEventListener('change',e=>{if(e.target.checked)this.confirmed.add(this.index);else this.confirmed.delete(this.index);this.shadowRoot.querySelector('[data-next]').disabled=!e.target.checked;});
      this.shadowRoot.querySelector('[data-back]')?.addEventListener('click',()=>{this.index--;this.render();});
      this.shadowRoot.querySelector('[data-next]').addEventListener('click',()=>{if(!this.confirmed.has(this.index))return;if(this.index<rows.length-1){this.index++;this.render();return;}if(this.confirmed.size!==rows.length)return;const ok=R()?.completeLearning();if(ok===false){this.error='Could not save completion on this device. Please try again.';this.render();return;}try{localStorage.removeItem('mewlink-learning-required');}catch(_){}location.hash='done';});
    }
  }
  customElements.define('mew-important-notifications',Notifications);
  customElements.define('mew-care-alerts',Alerts);
  customElements.define('mew-care-basics',Basics);
  customElements.define('mew-learn-basics',LearnBasics);
})();
